// Some portions generated by Codex
package org.eclipse.rdf4j.common.iteration;

import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertNotNull;
import static org.junit.jupiter.api.Assertions.assertSame;
import static org.junit.jupiter.api.Assertions.assertThrows;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.util.concurrent.CountDownLatch;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.Future;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicReference;

import org.junit.jupiter.api.Test;

class TimeoutSchedulingBehaviorTest {

	private static final long TIMEOUT_MILLIS = 100;
	private static final long FUTURE_TIMEOUT_SECONDS = 5;
	private static final long HOUR_MILLIS = TimeUnit.HOURS.toMillis(1);

	@Test
	void nestedGuardCloseClearsItsInterruptWithoutFiringOuterGuard() {
		try {
			try (InterruptingTimeLimit outer = InterruptingTimeLimit.start(HOUR_MILLIS)) {
				try (InterruptingTimeLimit inner = InterruptingTimeLimit.start(0)) {
					assertTrue(inner.fired());
					assertTrue(Thread.currentThread().isInterrupted());
				}
				assertFalse(Thread.currentThread().isInterrupted(),
						"closing the inner fired guard clears its interrupt");
				assertFalse(outer.fired(), "the inner guard must not fire the still-active outer guard");
				assertTrue(outer.remainingMillis() > 0);
			}
		} finally {
			Thread.interrupted();
		}
	}

	@Test
	void unfiredInnerGuardKeepsInterruptFromFiredOuterGuard() {
		try {
			try (InterruptingTimeLimit outer = InterruptingTimeLimit.start(0)) {
				assertTrue(outer.fired());
				assertTrue(Thread.currentThread().isInterrupted());
				try (InterruptingTimeLimit inner = InterruptingTimeLimit.start(HOUR_MILLIS)) {
					assertFalse(inner.fired());
				}
				assertTrue(Thread.currentThread().isInterrupted(),
						"an unfired inner guard must preserve the interrupt");
			}
			assertFalse(Thread.currentThread().isInterrupted(), "closing the fired outer guard clears its interrupt");
		} finally {
			Thread.interrupted();
		}
	}

	@Test
	void unrelatedThreadInterruptSurvivesUnfiredGuardClose() throws Exception {
		ExecutorService executor = Executors.newSingleThreadExecutor();
		CountDownLatch guardStarted = new CountDownLatch(1);
		AtomicReference<Thread> ownerThread = new AtomicReference<>();
		Future<?> guardedTask = null;
		try {
			guardedTask = executor.submit(() -> {
				Thread owner = Thread.currentThread();
				ownerThread.set(owner);
				InterruptingTimeLimit limit = InterruptingTimeLimit.start(HOUR_MILLIS);
				try {
					guardStarted.countDown();
					assertThrows(InterruptedException.class,
							() -> new CountDownLatch(1).await(FUTURE_TIMEOUT_SECONDS, TimeUnit.SECONDS));
					assertFalse(limit.fired(), "the guard must remain unfired after an unrelated interrupt");
					owner.interrupt();
					limit.close();
					assertTrue(owner.isInterrupted(),
							"closing an unfired guard must preserve the other thread's interrupt");
				} finally {
					limit.close();
					Thread.interrupted();
				}
			});
			assertTrue(guardStarted.await(FUTURE_TIMEOUT_SECONDS, TimeUnit.SECONDS),
					"the worker must start its guard before the external interrupt");
			Thread owner = ownerThread.get();
			assertNotNull(owner);
			owner.interrupt();
			guardedTask.get(FUTURE_TIMEOUT_SECONDS, TimeUnit.SECONDS);
		} finally {
			Thread owner = ownerThread.get();
			if (guardedTask != null && !guardedTask.isDone() && owner != null) {
				owner.interrupt();
			}
			executor.shutdownNow();
			assertTrue(executor.awaitTermination(FUTURE_TIMEOUT_SECONDS, TimeUnit.SECONDS),
					"the guarded owner worker must finish");
		}
	}

	@Test
	void closeAndFireOrdersLeaveAReusedOwnerThreadUninterrupted() throws Exception {
		ExecutorService executor = Executors.newSingleThreadExecutor();
		try {
			Future<Thread> ownerAfterClose = executor.submit(() -> {
				Thread owner = Thread.currentThread();
				InterruptingTimeLimit limit = InterruptingTimeLimit.start(HOUR_MILLIS);
				try {
					assertFalse(limit.fired(), "the close-first guard must still be unfired");
					limit.close();
					assertFalse(limit.fired(), "the close-first guard must not fire during close");
					assertFalse(owner.isInterrupted(), "a canceled timeout must not leave an interrupt on its owner");
					return owner;
				} finally {
					limit.close();
					Thread.interrupted();
				}
			});
			Thread owner = ownerAfterClose.get(FUTURE_TIMEOUT_SECONDS, TimeUnit.SECONDS);

			Future<Thread> ownerAfterFire = executor.submit(() -> {
				Thread current = Thread.currentThread();
				assertSame(owner, current, "the executor must reuse the timeout owner thread");
				InterruptingTimeLimit limit = InterruptingTimeLimit.start(TIMEOUT_MILLIS);
				try {
					assertThrows(InterruptedException.class,
							() -> new CountDownLatch(1).await(FUTURE_TIMEOUT_SECONDS, TimeUnit.SECONDS));
					assertTrue(limit.fired(), "the timeout must win before this guard is closed");
				} finally {
					limit.close();
				}
				assertFalse(current.isInterrupted(), "closing a fired guard must clear its interrupt before reuse");
				return current;
			});
			assertSame(owner, ownerAfterFire.get(FUTURE_TIMEOUT_SECONDS, TimeUnit.SECONDS));

			Future<?> reusedOwnerCheck = executor.submit(() -> {
				assertSame(owner, Thread.currentThread(), "the same owner thread must run subsequent work");
				assertFalse(Thread.currentThread().isInterrupted(), "closed guards must not interrupt later work");
			});
			reusedOwnerCheck.get(FUTURE_TIMEOUT_SECONDS, TimeUnit.SECONDS);
		} finally {
			executor.shutdownNow();
			assertTrue(executor.awaitTermination(FUTURE_TIMEOUT_SECONDS, TimeUnit.SECONDS),
					"all reused-owner tasks must finish");
		}
	}
}
